CREATE OR REPLACE FUNCTION public.refresh_batch_expiration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP <> 'INSERT' THEN
  UPDATE items SET "exDate" = (SELECT MIN("batch_exDate") FROM batches
   WHERE item_id = OLD.item_id AND batch_stock > 0) WHERE item_id = OLD.item_id;
 END IF;
 IF TG_OP <> 'DELETE' THEN
  UPDATE items SET "exDate" = (SELECT MIN("batch_exDate") FROM batches
   WHERE item_id = NEW.item_id AND batch_stock > 0) WHERE item_id = NEW.item_id;
 END IF;
 RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_salary_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END;
$function$
;

